using System.Net;
using System.Text;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

public sealed record CapturedRequest(string Method, string Path, string? ContentType, string Body);

/// <summary>Real HTTP server on loopback that plays the provider with a canned answer and records what it received.</summary>
public sealed class FakeProviderServer : IDisposable
{
    private readonly HttpListener listener = new();
    private readonly int status;
    private readonly string body;
    private readonly Task loop;

    public FakeProviderServer(int status, string body)
    {
        this.status = status;
        this.body = body;
        var port = GetFreePort();
        BaseAddress = new Uri($"http://127.0.0.1:{port}");
        listener.Prefixes.Add($"http://127.0.0.1:{port}/");
        listener.Start();
        loop = Task.Run(Serve);
    }

    public Uri BaseAddress { get; }

    public List<CapturedRequest> Requests { get; } = [];

    private async Task Serve()
    {
        while (listener.IsListening)
        {
            HttpListenerContext ctx;
            try { ctx = await listener.GetContextAsync(); }
            catch (Exception) { return; }

            using var reader = new StreamReader(ctx.Request.InputStream, Encoding.UTF8);
            var received = await reader.ReadToEndAsync();
            lock (Requests)
                Requests.Add(new CapturedRequest(ctx.Request.HttpMethod, ctx.Request.Url!.AbsolutePath, ctx.Request.ContentType, received));

            var bytes = Encoding.UTF8.GetBytes(body);
            ctx.Response.StatusCode = status;
            ctx.Response.ContentType = "application/json";
            ctx.Response.ContentLength64 = bytes.Length;
            await ctx.Response.OutputStream.WriteAsync(bytes);
            ctx.Response.Close();
        }
    }

    private static int GetFreePort()
    {
        var tcp = new System.Net.Sockets.TcpListener(IPAddress.Loopback, 0);
        tcp.Start();
        var port = ((IPEndPoint)tcp.LocalEndpoint).Port;
        tcp.Stop();
        return port;
    }

    public void Dispose()
    {
        listener.Close();
        loop.Wait(TimeSpan.FromSeconds(2));
    }
}
